          /* HUB GUIDE ---------------------------------------------------------
           * EVENT BINDING
           * resizeHandle.onpointercancel = finish; — connects the control or lifecycle event to its handler.
           * ------------------------------------------------------------------- */
          resizeHandle.onpointercancel = finish;
          resizeHandle.onlostpointercapture = finish;
